if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!is_string($_POST['csrf']??null)||!hash_equals($_SESSION['csrf'],$_POST['csrf'])){$errors[]='Sesi berubah. Muat ulang halaman lalu coba lagi.';http_response_code(403);}
    $values=[];
