    if(!isset($methods[$values['payment']]))$errors[]='Pilih preferensi pembayaran.';
    if(!phone($values['phone']))$errors[]='Nomor WhatsApp harus menggunakan nomor Indonesia yang valid.';
    if(!preg_match('/^[0-9]{5}$/D',$values['postal']))$errors[]='Kode pos harus 5 angka.';
    if(!$errors){$_SESSION['checkout_draft']=$values;header('Location: checkout.php?review=1');exit;}
}
$review=isset($_GET['review']) && isset($_SESSION['checkout_draft']) && !$errors;
$total=0;$lines=[];foreach($cart as $row){$amount=$row['product']['price']*$row['qty'];$total+=$amount;$lines[]=$row['product']['name'].' × '.$row['qty'].' — '.rupiah($amount);}
shop_header($review?'Tinjau permintaan':'Checkout',$user);
?>
